<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT p.id,p.name,pp.price FROM products p JOIN product_prices pp ON pp.product_id=p.id AND pp.level_id=? WHERE p.is_active=1');$q->execute([$u['level_id']]);$ps=$q->fetchAll();$title='Order';require __DIR__.'/../layouts/head.php';?><div class="flex"><?php require __DIR__.'/../components/sidebar.php';?><main class="p-8 flex-1"><h1 class="text-2xl font-semibold">Order IMEI</h1><form id="f" class="saas-card p-6 mt-6 max-w-xl space-y-4"><select class="field" name="product_id" required><?php foreach($ps as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> — Rp<?=number_format($p['price'],0,',','.')?></option><?php endforeach?></select><input class="field font-mono" name="imei" maxlength="15" pattern="[0-9]{15}" oninput="cleanImei(this)" required><button class="btn btn-dark">Create order</button></form></main></div><script>f.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))}),j=await r.json();Swal.fire(j.ok?'Success':'Error',j.ok?j.data.order_number:j.message,j.ok?'success':'error')}</script><?php require __DIR__.'/../layouts/foot.php';?>